.cookie-banner { position: fixed; left: 20px; right: 20px; bottom: 20px; z-index: 120; border: 1px solid var(--line-strong); background: rgba(7,17,29,.96); backdrop-filter: blur(18px); border-radius: 22px; box-shadow: var(--shadow); padding: 18px; display: none; grid-template-columns: 1fr auto; gap: 18px; align-items: center; }
.cookie-banner.active { display: grid; }
