const fs=require('fs'), path=require('path');
const dir='/app/output';
const files=fs.readdirSync(dir).filter(f=>f.endsWith('.html'));
const existing=new Set([...files, 'assets/styles.css', 'assets/app.js']);
let broken=[];
for (const file of files) {
  const html=fs.readFileSync(path.join(dir,file),'utf8');
  for (const [,href] of html.matchAll(/href="([^"]+)"/g)) {
    if (/^(https?:|#|mailto:)/.test(href)) continue;
    const target=href.split('#')[0];
    if (target && !existing.has(target)) broken.push(`${file} -> ${href}`);
  }
  for (const [,src] of html.matchAll(/src="([^"]+)"/g)) {
    if (/^https?:/.test(src)) continue;
    if (!existing.has(src)) broken.push(`${file} -> ${src}`);
  }
}
console.log(broken.length ? broken.join('\n') : 'No broken relative file links.');
